new='''/**
 * Clones a project into a new one of the same workspace (ADR 0012). Gated
 * like a creation, plus a read of the source; when issues are included, the
 * whole batch of live issues is checked against the per-project quota before
 * anything is written. Copies are a fresh start: default status, unassigned,
 * authored by the actor and renumbered from 1 in the source's order.
 *
 * Publishes `project.cloned` only — not `project.created` nor one
 * `issue.created` per copy; search and usage react to `project.cloned`.
 */
export async function cloneProject(
  actor: Actor,
  input: CloneProjectInput,
): Promise<Project> {
  assertOrgScope(actor, input.orgId);

  const source = requireFound(
    await projectRepo.findProjectById(input.orgId, input.projectId),
    "Project",
    input.projectId,
  );
  assertCan(actor, "project:read", projectResource(source));
  assertNotArchived("Project", source.id, source);
  assertCan(actor, "project:create", orgResource(input.orgId));

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );

  const used = await projectRepo.countProjects(input.orgId);
  if (wouldExceedLimit(org.plan, "projects", used)) {
    throw new Error(
      `Plan ${org.plan} allows ${used} projects; upgrade to add another`,
    );
  }

  const sourceIssues = input.includeIssues
    ? await listLiveIssuesByNumber(input.orgId, source.id)
    : [];
  if (
    sourceIssues.length > 0 &&
    wouldExceedLimit(org.plan, "issuesPerProject", 0, sourceIssues.length)
  ) {
    throw new Error(
      `Plan ${org.plan} allows no more issues in project ${input.key}: ` +
        `cloning would copy ${sourceIssues.length}`,
    );
  }

  const slug = await suggestProjectSlug(input.orgId, input.slug);

  const clone = await projectRepo.insertProject({
    orgId: input.orgId,
    name: input.name,
    slug,
    key: input.key,
    description: source.description,
    visibility: source.visibility,
    leadId: source.leadId,
    color: source.color,
    targetDate: null,
  });

  const status = defaultIssueStatus(org.settings.defaultIssueStatus);
  let number = 0;
  for (const issue of sourceIssues) {
    number += 1;
    await issueRepo.insertIssue(
      {
        orgId: input.orgId,
        projectId: clone.id,
        title: issue.title,
        description: issue.description,
        status,
        priority: issue.priority,
        assigneeId: null,
        parentId: null,
        estimate: issue.estimate,
        dueAt: issue.dueAt,
        labelIds: [...issue.labelIds],
      },
      actor.userId,
      number,
    );
  }

  await emit("project.cloned", {
    ...actorEnvelope(actor),
    projectId: clone.id,
    sourceProjectId: source.id,
    issuesCopied: sourceIssues.length,
  });

  return clone;
}

'''
