s=s.rstrip('\n')+'''

/** Every live issue of a project, walking all pages, in issue-number order. */
async function listLiveIssuesByNumber(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<readonly Issue[]> {
  const all: Issue[] = [];
  let cursor: string | null = null;

  do {
    const page = await issueRepo.listIssues({
      orgId,
      projectId,
      limit: 100,
      cursor,
    });
    all.push(...page.items);
    cursor = page.nextCursor;
  } while (cursor !== null);

  return all.sort((a, b) => a.number - b.number);
}

/**
 * `OrganizationSettings.defaultIssueStatus` is stored as a plain string, so it
 * is re-validated against the enum before it is applied.
 */
function defaultIssueStatus(stored: string): IssueStatus {
  const parsed = issueStatusSchema.safeParse(stored);
  return parsed.success ? parsed.data : "backlog";
}
'''
