cat > tests/zz-tmp-clone.test.ts <<'EOF'
import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";
vi.mock("@/lib/logger", async () => (await import("./server/_support/doubles/misc")).loggerModule);
vi.mock("@/lib/rate-limit", async () => (await import("./server/_support/doubles/misc")).rateLimitModule);
import { subscribe } from "@/lib/event-bus";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import * as commentService from "@/server/services/comment-service";
import * as issueService from "@/server/services/issue-service";
import * as projectService from "@/server/services/project-service";
import * as searchService from "@/server/services/search-service";
import { listActivity, registerActivityListeners } from "@/server/services/activity-service";
import { registerUsageListeners } from "@/server/services/usage-service";
import { activityFilterSchema } from "@/schemas/activity";
import { cloneProjectSchema } from "@/schemas/project";
import { createTenant, issueInput, useTemporaryDatabase } from "./server/_support/fixtures";

let cleanup: () => void;
const offs: (() => void)[] = [];
beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  offs.push(registerActivityListeners(), searchService.registerSearchListeners(), registerUsageListeners());
});
afterAll(() => { offs.forEach((o) => o()); cleanup(); });

describe("clone", () => {
  it("clones", async () => {
    const t = await createTenant("clone1", "growth");
    const a = await issueService.createIssue(t.actors.member, { ...issueInput(t.org.id, t.project.id, { title: "Alpha quuxword", assigneeId: t.userIds.admin }), status: "in_progress" as never });
    const b = await issueService.createIssue(t.actors.member, issueInput(t.org.id, t.project.id, { title: "Bravo thing" }));
    const c = await issueService.createIssue(t.actors.member, issueInput(t.org.id, t.project.id, { title: "Charlie arch" }));
    await issueService.archiveIssue(t.actors.admin, t.org.id, c.id);
    await commentService.createComment(t.actors.member, { orgId: t.org.id, issueId: a.id, body: "hi", parentId: null, mentionedUserIds: [] });
    const before = await usageRepo.getUsage(t.org.id);
    const seen: unknown[] = [];
    const created: unknown[] = [];
    offs.push(subscribe("project.cloned", (p) => { seen.push(p); }));
    offs.push(subscribe("issue.created", (p) => { created.push(p); }));
    offs.push(subscribe("project.created", (p) => { created.push(p); }));
    const input = cloneProjectSchema.parse({ orgId: t.org.id, projectId: t.project.id, name: "Copy", slug: "platform", key: "CPY" });
    const clone = await projectService.cloneProject(t.actors.member, input);
    console.log(clone);
    expect(clone.slug).toBe("platform-2");
    const page = await issueRepo.listIssues({ orgId: t.org.id, projectId: clone.id, limit: 100, includeArchived: true });
    console.log(page.items.map((i) => [i.number, i.title, i.status, i.assigneeId, i.authorId]));
    expect(page.total).toBe(2);
    expect(seen).toEqual([expect.objectContaining({ projectId: clone.id, sourceProjectId: t.project.id, issuesCopied: 2, actorId: t.userIds.member })]);
    expect(created).toHaveLength(0);
    const act = await listActivity(t.actors.member, activityFilterSchema.parse({ orgId: t.org.id, action: ["project.cloned"] }));
    console.log(act.items);
    const hits = await searchService.search(t.actors.member, { orgId: t.org.id, q: "quuxword", kinds: ["issue"], limit: 25, cursor: null });
    console.log(hits.items);
    expect(hits.total).toBe(2);
    const after = await usageRepo.getUsage(t.org.id);
    console.log(before, after);
